function batchAcceptBidWithCredit(
    bytes32[] calldata marketplaceIds,
    bytes[] calldata payloads,
    DataTypes.Credit[] calldata credits,
    uint256[] calldata punkIndexes,
    uint16 referralCode
) external nonReentrant {
    for (uint256 i = 0; i < punkIndexes.length; i++) {
        Punk.buyPunk(punkIndexes[i]);
        Punk.transferPunk(proxy, punkIndexes[i]);
        // gatewayProxy is the sender of this function, not the original gateway
        WPunk.mint(punkIndexes[i]);

        IERC721(wpunk).safeTransferFrom(
            address(this),
            msg.sender,
            punkIndexes[i]
        );
    }
    Pool.batchAcceptBidWithCredit(
        marketplaceIds,
        payloads,
        credits,
        msg.sender,
        referralCode
    );
}

function mint(uint256 punkIndex) public override whenNotPaused {
    address sender = _msgSender();

    UserProxy proxy = UserProxy(_proxies[sender]);
    require(
        proxy.transfer(address(_punkContract), punkIndex),
        "PunkWrapper: transfer fail"
    );
    _mint(sender, punkIndex);
}

function acceptBidWithCredit(
    bytes32 marketplaceId,
    bytes calldata payload,
    DataTypes.Credit calldata credit,
    uint256[] calldata punkIndexes,
    uint16 referralCode
) external nonReentrant {
    for (uint256 i = 0; i < punkIndexes.length; i++) {
        Punk.buyPunk(punkIndexes[i]);
        Punk.transferPunk(proxy, punkIndexes[i]);
        // gatewayProxy is the sender of this function, not the original gateway
        WPunk.mint(punkIndexes[i]);

        IERC721(wpunk).safeTransferFrom(
            address(this),
            msg.sender,
            punkIndexes[i]
        );
    }
    Pool.acceptBidWithCredit(
        marketplaceId,
        payload,
        credit,
        msg.sender,
        referralCode
    );
}

function supplyPunk(
    DataTypes.ERC721SupplyParams[] calldata punkIndexes,
    address onBehalfOf,
    uint16 referralCode
) external nonReentrant {
    for (uint256 i = 0; i < punkIndexes.length; i++) {
        Punk.buyPunk(punkIndexes[i].tokenId);
        Punk.transferPunk(proxy, punkIndexes[i].tokenId);
        // gatewayProxy is the sender of this function, not the original gateway
        WPunk.mint(punkIndexes[i].tokenId);
    }

    Pool.supplyERC721(
        address(WPunk),
        punkIndexes,
        onBehalfOf,
        referralCode
    );
}

detail:
# Vulnerability details

## Impact
The debt tokens are being transferred before calculating the interest rates. But the interest rate calculation function assumes that debt token has not yet been sent thus the outcome `currentLiquidityRate` will be incorrect

## Proof of Concept
1. Liquidator L1 calls  for a position whose health factor <1

```
function executeLiquidateERC20(
        mapping(address => DataTypes.ReserveData) storage reservesData,
        mapping(uint256 => address) storage reservesList,
        mapping(address => DataTypes.UserConfigurationMap) storage usersConfig,
        DataTypes.ExecuteLiquidateParams memory params
    ) external returns (uint256) {

...
 _burnDebtTokens(liquidationAssetReserve, params, vars);
...
}
```

2. This internally calls 

```
    function _burnDebtTokens(
        DataTypes.ReserveData storage liquidationAssetReserve,
        DataTypes.ExecuteLiquidateParams memory params,
        ExecuteLiquidateLocalVars memory vars
    ) internal {
       ...

        // Transfers the debt asset being repaid to the xToken, where the liquidity is kept
        IERC20(params.liquidationAsset).safeTransferFrom(
            vars.payer,
            vars.liquidationAssetReserveCache.xTokenAddress,
            vars.actualLiquidationAmount
        );
...
        // Update borrow & supply rate
        liquidationAssetReserve.updateInterestRates(
            vars.liquidationAssetReserveCache,
            params.liquidationAsset,
            vars.actualLiquidationAmount,
            0
        );
    }
```

3. Basically first it transfers the debt asset to xToken using below. This increases the balance of xTokenAddress for liquidationAsset

```
IERC20(params.liquidationAsset).safeTransferFrom(
            vars.payer,
            vars.liquidationAssetReserveCache.xTokenAddress,
            vars.actualLiquidationAmount
        );
```

4. Now `updateInterestRates` function is called on ReserveLogic.sol#L169

```
function updateInterestRates(
        DataTypes.ReserveData storage reserve,
        DataTypes.ReserveCache memory reserveCache,
        address reserveAddress,
        uint256 liquidityAdded,
        uint256 liquidityTaken
    ) internal {
...
(
            vars.nextLiquidityRate,
            vars.nextVariableRate
        ) = IReserveInterestRateStrategy(reserve.interestRateStrategyAddress)
            .calculateInterestRates(
                DataTypes.CalculateInterestRatesParams({
                    liquidityAdded: liquidityAdded,
                    liquidityTaken: liquidityTaken,
                    totalVariableDebt: vars.totalVariableDebt,
                    reserveFactor: reserveCache.reserveFactor,
                    reserve: reserveAddress,
                    xToken: reserveCache.xTokenAddress
                })
            );
...
}
```

5. Finally call to `calculateInterestRates` function on DefaultReserveInterestRateStrategy#L127 contract is made which calculates the interest rate

```
function calculateInterestRates(
        DataTypes.CalculateInterestRatesParams calldata params
    ) external view override returns (uint256, uint256) {
...
if (vars.totalDebt != 0) {
            vars.availableLiquidity =
                IToken(params.reserve).balanceOf(params.xToken) +
                params.liquidityAdded -
                params.liquidityTaken;

            vars.availableLiquidityPlusDebt =
                vars.availableLiquidity +
                vars.totalDebt;
            vars.borrowUsageRatio = vars.totalDebt.rayDiv(
                vars.availableLiquidityPlusDebt
            );
            vars.supplyUsageRatio = vars.totalDebt.rayDiv(
                vars.availableLiquidityPlusDebt
            );
        }
...
vars.currentLiquidityRate = vars
            .currentVariableBorrowRate
            .rayMul(vars.supplyUsageRatio)
            .percentMul(
                PercentageMath.PERCENTAGE_FACTOR - params.reserveFactor
            );

        return (vars.currentLiquidityRate, vars.currentVariableBorrowRate);
}
```

6. As we can see in above code, `vars.availableLiquidity` is calculated as `IToken(params.reserve).balanceOf(params.xToken) +params.liquidityAdded - params.liquidityTaken`

7. But the problem is that debt token is already transferred to `xToken` which means `xToken` already consist of `params.liquidityAdded`. Hence the calculation ultimately becomes `(xTokenBeforeBalance+params.liquidityAdded) +params.liquidityAdded - params.liquidityTaken`

8. This is incorrect and would lead to higher `vars.availableLiquidity` which ultimately impacts the `currentLiquidityRate`

## Recommended Mitigation Steps
Transfer the debt asset post interest calculation

```
function _burnDebtTokens(
        DataTypes.ReserveData storage liquidationAssetReserve,
        DataTypes.ExecuteLiquidateParams memory params,
        ExecuteLiquidateLocalVars memory vars
    ) internal {
IPToken(vars.liquidationAssetReserveCache.xTokenAddress)
            .handleRepayment(params.liquidator, vars.actualLiquidationAmount);
        // Burn borrower's debt token
        vars
            .liquidationAssetReserveCache
            .nextScaledVariableDebt = IVariableDebtToken(
            vars.liquidationAssetReserveCache.variableDebtTokenAddress
        ).burn(
                params.borrower,
                vars.actualLiquidationAmount,
                vars.liquidationAssetReserveCache.nextVariableBorrowIndex
            );

liquidationAssetReserve.updateInterestRates(
            vars.liquidationAssetReserveCache,
            params.liquidationAsset,
            vars.actualLiquidationAmount,
            0
        );
IERC20(params.liquidationAsset).safeTransferFrom(
            vars.payer,
            vars.liquidationAssetReserveCache.xTokenAddress,
            vars.actualLiquidationAmount
        );
...
...
}
```

code:
function _burnDebtTokens(
    DataTypes.ReserveData storage liquidationAssetReserve,
    DataTypes.ExecuteLiquidateParams memory params,
    ExecuteLiquidateLocalVars memory vars
) internal {
    _depositETH(params, vars);

    // Transfers the debt asset being repaid to the xToken, where the liquidity is kept
    IERC20(params.liquidationAsset).safeTransferFrom(
        vars.payer,
        vars.liquidationAssetReserveCache.xTokenAddress,
        vars.actualLiquidationAmount
    );
    // Handle payment
    IPToken(vars.liquidationAssetReserveCache.xTokenAddress)
        .handleRepayment(params.liquidator, vars.actualLiquidationAmount);
    // Burn borrower's debt token
    vars
        .liquidationAssetReserveCache
        .nextScaledVariableDebt = IVariableDebtToken(
        vars.liquidationAssetReserveCache.variableDebtTokenAddress
    ).burn(
            params.borrower,
            vars.actualLiquidationAmount,
            vars.liquidationAssetReserveCache.nextVariableBorrowIndex
        );
    // Update borrow & supply rate
    liquidationAssetReserve.updateInterestRates(
        vars.liquidationAssetReserveCache,
        params.liquidationAsset,
        vars.actualLiquidationAmount,
        0
    );
}

function executeLiquidateERC20(
    mapping(address => DataTypes.ReserveData) storage reservesData,
    mapping(uint256 => address) storage reservesList,
    mapping(address => DataTypes.UserConfigurationMap) storage usersConfig,
    DataTypes.ExecuteLiquidateParams memory params
) external returns (uint256) {
    ExecuteLiquidateLocalVars memory vars;

    DataTypes.ReserveData storage collateralReserve = reservesData[
        params.collateralAsset
    ];
    DataTypes.ReserveData storage liquidationAssetReserve = reservesData[
        params.liquidationAsset
    ];
    DataTypes.UserConfigurationMap storage userConfig = usersConfig[
        params.borrower
    ];
    vars.liquidationAssetReserveCache = liquidationAssetReserve.cache();
    liquidationAssetReserve.updateState(vars.liquidationAssetReserveCache);

    (, , , , , , , vars.healthFactor, , ) = GenericLogic
        .calculateUserAccountData(
            reservesData,
            reservesList,
            DataTypes.CalculateUserAccountDataParams({
                userConfig: userConfig,
                reservesCount: params.reservesCount,
                user: params.borrower,
                oracle: params.priceOracle
            })
        );

    (vars.userDebt, vars.actualLiquidationAmount) = _calculateDebt(
        params,
        vars
    );

    (vars.collateralXToken, vars.liquidationBonus) = _getConfigurationData(
        collateralReserve
    );

    (
        vars.userCollateral,
        vars.actualCollateralToLiquidate,
        vars.actualLiquidationAmount,
        vars.liquidationProtocolFee
    ) = _calculateERC20LiquidationParameters(
        collateralReserve,
        params,
        vars
    );

    ValidationLogic.validateLiquidateERC20(
        userConfig,
        collateralReserve,
        DataTypes.ValidateLiquidateERC20Params({
            liquidationAssetReserveCache: vars.liquidationAssetReserveCache,
            weth: params.weth,
            liquidationAmount: params.liquidationAmount,
            actualLiquidationAmount: vars.actualLiquidationAmount,
            liquidationAsset: params.liquidationAsset,
            totalDebt: vars.userDebt,
            healthFactor: vars.healthFactor,
            priceOracleSentinel: params.priceOracleSentinel
        })
    );

    if (vars.userDebt == vars.actualLiquidationAmount) {
        userConfig.setBorrowing(liquidationAssetReserve.id, false);
    }

    // If the collateral being liquidated is equal to the user balance,
    // we set the currency as not being used as collateral anymore
    if (
        vars.actualCollateralToLiquidate + vars.liquidationProtocolFee ==
        vars.userCollateral
    ) {
        userConfig.setUsingAsCollateral(collateralReserve.id, false);
        emit ReserveUsedAsCollateralDisabled(
            params.collateralAsset,
            params.borrower
        );
    }

    // Transfer fee to treasury if it is non-zero
    if (vars.liquidationProtocolFee != 0) {
        IPToken(vars.collateralXToken).transferOnLiquidation(
            params.borrower,
            IPToken(vars.collateralXToken).RESERVE_TREASURY_ADDRESS(),
            vars.liquidationProtocolFee
        );
    }

    _burnDebtTokens(liquidationAssetReserve, params, vars);

    if (params.receiveXToken) {
        _liquidatePTokens(usersConfig, collateralReserve, params, vars);
    } else {
        _burnCollateralPTokens(collateralReserve, params, vars);
    }

    emit LiquidateERC20(
        params.collateralAsset,
        params.liquidationAsset,
        params.borrower,
        vars.actualLiquidationAmount,
        vars.actualCollateralToLiquidate,
        params.liquidator,
        params.receiveXToken
    );

    return vars.actualLiquidationAmount;
}

