function executeLiquidateERC721(
    mapping(address => DataTypes.ReserveData) storage reservesData,
    mapping(uint256 => address) storage reservesList,
    mapping(address => DataTypes.UserConfigurationMap) storage usersConfig,
    DataTypes.ExecuteLiquidateParams memory params
) external returns (uint256) {
    ExecuteLiquidateLocalVars memory vars;

    DataTypes.ReserveData storage collateralReserve = reservesData[
        params.collateralAsset
    ];
    DataTypes.ReserveData storage liquidationAssetReserve = reservesData[
        params.liquidationAsset
    ];
    DataTypes.UserConfigurationMap storage userConfig = usersConfig[
        params.borrower
    ];

    vars.liquidationAssetReserveId = liquidationAssetReserve.id;
    vars.liquidationAssetReserveCache = liquidationAssetReserve.cache();
    // liquidationAssetReserve.updateState(vars.liquidationAssetReserveCache);

    vars.auctionStrategyAddress = collateralReserve.auctionStrategyAddress;
    vars.auctionEnabled = vars.auctionStrategyAddress != address(0);

    (
        vars.userGlobalCollateral,
        ,
        vars.userGlobalDebt, //in base currency
        ,
        ,
        ,
        ,
        ,
        vars.healthFactor,

    ) = GenericLogic.calculateUserAccountData(
        reservesData,
        reservesList,
        DataTypes.CalculateUserAccountDataParams({
            userConfig: userConfig,
            reservesCount: params.reservesCount,
            user: params.borrower,
            oracle: params.priceOracle
        })
    );

    (vars.collateralXToken, vars.liquidationBonus) = _getConfigurationData(
        collateralReserve
    );
    if (vars.auctionEnabled) {
        vars.liquidationBonus = PercentageMath.PERCENTAGE_FACTOR;
    }

    (
        vars.userCollateral,
        vars.actualLiquidationAmount,
        vars.liquidationProtocolFee,
        vars.userGlobalDebt
    ) = _calculateERC721LiquidationParameters(
        collateralReserve,
        params,
        vars
    );

    ValidationLogic.validateLiquidateERC721(
        reservesData,
        userConfig,
        collateralReserve,
        DataTypes.ValidateLiquidateERC721Params({
            liquidationAssetReserveCache: vars.liquidationAssetReserveCache,
            liquidator: params.liquidator,
            borrower: params.borrower,
            globalDebt: vars.userGlobalDebt,
            actualLiquidationAmount: vars.actualLiquidationAmount,
            maxLiquidationAmount: params.liquidationAmount,
            healthFactor: vars.healthFactor,
            priceOracleSentinel: params.priceOracleSentinel,
            collateralAsset: params.collateralAsset,
            tokenId: params.collateralTokenId,
            xTokenAddress: vars.collateralXToken,
            auctionEnabled: vars.auctionEnabled,
            auctionRecoveryHealthFactor: params.auctionRecoveryHealthFactor
        })
    );

    if (vars.auctionEnabled) {
        IAuctionableERC721(vars.collateralXToken).endAuction(
            params.collateralTokenId
        );
        emit AuctionEnded(
            params.borrower,
            params.collateralAsset,
            params.collateralTokenId
        );
    }

    _supplyNewCollateral(reservesData, userConfig, params, vars);

    // If the collateral being liquidated is equal to the user balance,
    // we set the currency as not being used as collateral anymore
    if (vars.userCollateral == 1) {
        userConfig.setUsingAsCollateral(collateralReserve.id, false);
        emit ReserveUsedAsCollateralDisabled(
            params.collateralAsset,
            params.borrower
        );
    }

    // Transfer fee to treasury if it is non-zero
    if (vars.liquidationProtocolFee != 0) {
        IERC20(params.liquidationAsset).safeTransferFrom(
            vars.payer,
            IPToken(vars.liquidationAssetReserveCache.xTokenAddress)
                .RESERVE_TREASURY_ADDRESS(),
            vars.liquidationProtocolFee
        );
    }

    if (params.receiveXToken) {
        INToken(vars.collateralXToken).transferOnLiquidation(
            params.borrower,
            params.liquidator,
            params.collateralTokenId
        );
    } else {
        _burnCollateralNTokens(params, vars);
    }

    emit LiquidateERC721(
        params.collateralAsset,
        params.liquidationAsset,
        params.borrower,
        vars.actualLiquidationAmount,
        params.collateralTokenId,
        params.liquidator,
        params.receiveXToken
    );

    return vars.actualLiquidationAmount;
}

function _removeFeeder(address _feeder)
    internal
    onlyWhenFeederExisted(_feeder)
{
    uint8 feederIndex = feederPositionMap[_feeder].index;
    if (feederIndex >= 0 && feeders[feederIndex] == _feeder) {
        feeders[feederIndex] = feeders[feeders.length - 1];
        feeders.pop();
    }
    delete feederPositionMap[_feeder];
    revokeRole(UPDATER_ROLE, _feeder);
    emit FeederRemoved(_feeder);
}

function _getAssetPrice(address oracle, address currentReserveAddress)
    internal
    view
    returns (uint256)
{
    return IPriceOracleGetter(oracle).getAssetPrice(currentReserveAddress);
}

function _getUserBalanceForERC721(
    DataTypes.CalculateUserAccountDataParams memory params,
    CalculateUserAccountDataVars memory vars
) private view returns (uint256 totalValue) {
    INToken nToken = INToken(vars.xTokenAddress);
    bool isAtomicPrice = nToken.getAtomicPricingConfig();
    if (isAtomicPrice) {
        uint256 totalBalance = nToken.balanceOf(params.user);

        for (uint256 index = 0; index < totalBalance; index++) {
            uint256 tokenId = nToken.tokenOfOwnerByIndex(
                params.user,
                index
            );
            if (
                ICollateralizableERC721(vars.xTokenAddress)
                    .isUsedAsCollateral(tokenId)
            ) {
                totalValue += _getTokenPrice(
                    params.oracle,
                    vars.currentReserveAddress,
                    tokenId
                );
            }
        }
    } else {
        uint256 assetPrice = _getAssetPrice(
            params.oracle,
            vars.currentReserveAddress
        );
        totalValue =
            ICollateralizableERC721(vars.xTokenAddress)
                .collateralizedBalanceOf(params.user) *
            assetPrice;
    }
}

function _finalizePrice(address _asset, uint256 _twap) internal {
    PriceInformation storage assetPriceMapEntry = assetPriceMap[_asset];
    assetPriceMapEntry.twap = _twap;
    assetPriceMapEntry.updatedAt = block.number;
    assetPriceMapEntry.updatedTimestamp = block.timestamp;
    emit AssetDataSet(
        _asset,
        assetPriceMapEntry.twap,
        assetPriceMapEntry.updatedAt
    );
}

function getTokenPrice(uint256 tokenId) public view returns (uint256) {
    UinswapV3PositionData memory positionData = getOnchainPositionData(
        tokenId
    );

    PairOracleData memory oracleData = _getOracleData(positionData);

    (uint256 liquidityAmount0, uint256 liquidityAmount1) = LiquidityAmounts
        .getAmountsForLiquidity(
            oracleData.sqrtPriceX96,
            TickMath.getSqrtRatioAtTick(positionData.tickLower),
            TickMath.getSqrtRatioAtTick(positionData.tickUpper),
            positionData.liquidity
        );

    (
        uint256 feeAmount0,
        uint256 feeAmount1
    ) = getLpFeeAmountFromPositionData(positionData);

    return
        (((liquidityAmount0 + feeAmount0) * oracleData.token0Price) /
            10**oracleData.token0Decimal) +
        (((liquidityAmount1 + feeAmount1) * oracleData.token1Price) /
            10**oracleData.token1Decimal);
}

function getSqrtRatioAtTick(int24 tick)
    internal
    pure
    returns (uint160 sqrtPriceX96)
{
    uint256 absTick = tick < 0
        ? uint256(-int256(tick))
        : uint256(int256(tick));
    require(absTick <= uint256(MAX_TICK), "T");

    uint256 ratio = absTick & 0x1 != 0
        ? 0xfffcb933bd6fad37aa2d162d1a594001
        : 0x100000000000000000000000000000000;
    if (absTick & 0x2 != 0)
        ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
    if (absTick & 0x4 != 0)
        ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
    if (absTick & 0x8 != 0)
        ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
    if (absTick & 0x10 != 0)
        ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
    if (absTick & 0x20 != 0)
        ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
    if (absTick & 0x40 != 0)
        ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
    if (absTick & 0x80 != 0)
        ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
    if (absTick & 0x100 != 0)
        ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
    if (absTick & 0x200 != 0)
        ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
    if (absTick & 0x400 != 0)
        ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
    if (absTick & 0x800 != 0)
        ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
    if (absTick & 0x1000 != 0)
        ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
    if (absTick & 0x2000 != 0)
        ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
    if (absTick & 0x4000 != 0)
        ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
    if (absTick & 0x8000 != 0)
        ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
    if (absTick & 0x10000 != 0)
        ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
    if (absTick & 0x20000 != 0)
        ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
    if (absTick & 0x40000 != 0)
        ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
    if (absTick & 0x80000 != 0)
        ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;

    if (tick > 0) ratio = type(uint256).max / ratio;

    // this divides by 1<<32 rounding up to go from a Q128.128 to a Q128.96.
    // we then downcast because we know the result always fits within 160 bits due to our tick input constraint
    // we round up in the division so getTickAtSqrtRatio of the output price is always consistent
    sqrtPriceX96 = uint160(
        (ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1)
    );
}

detail:
# Vulnerability details

## Impact
When the squared root of the Uniswap V3 position is calculated from the [`_getOracleData()` function](https://github.com/code-423n4/2022-11-paraspace/blob/main/paraspace-core/contracts/misc/UniswapV3OracleWrapper.sol#L221-L280), the price may return a very high number (in the case that the token1 decimals are strictly superior to the token0 decimals). See: https://github.com/code-423n4/2022-11-paraspace/blob/main/paraspace-core/contracts/misc/UniswapV3OracleWrapper.sol#L249-L260

The reason is that at the denominator, the `1E9` (10**9) value is hard-coded, but should take into account the delta between both decimals.
As a result, in the case of `token1Decimal > token0Decimal`, the  is going to return a huge value for the amount of token0 and token1 as the user position liquidity.

The , using this amount of liquidity to [calculate the token price](https://github.com/code-423n4/2022-11-paraspace/blob/main/paraspace-core/contracts/misc/UniswapV3OracleWrapper.sol#L176-L180) is as its turn going to return a huge value.

## Proof of Concept

This POC demonstrates in which case the returned squared root price of the position is over inflated

